from typing import List

class Solution:
    def maxTrionicSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 4:
            return -1

        INF = float('inf')
        # dp1: max sum of phase 1 (strictly increasing, at least 2 elements) ending at i
        # dp2: max sum of phase 2 (strictly decreasing, at least 2 elements) ending at i
        # dp3: max sum of phase 3 (strictly increasing, at least 2 elements) ending at i

        # State tracking:
        # inc1[i]: strictly increasing ending at i (length >= 1)
        # peak[i]: strictly increasing ending at i (length >= 2)
        # dec[i]: decreasing ending at i (transitioned from peak)
        # valley[i]: decreasing ending at i (length >= 2 in dec phase)
        # inc2[i]: second increasing ending at i (transitioned from valley)

        inc1 = nums[:]
        peak = [-INF] * n
        dec = [-INF] * n
        inc2 = [-INF] * n

        best = -INF
        for i in range(1, n):
            if nums[i] > nums[i - 1]:
                inc1[i] = max(nums[i], inc1[i - 1] + nums[i])
                peak[i] = inc1[i - 1] + nums[i]
                if inc2[i - 1] != -INF:
                    inc2[i] = max(inc2[i], inc2[i - 1] + nums[i])
            if nums[i] < nums[i - 1]:
                if peak[i - 1] != -INF:
                    dec[i] = max(dec[i], peak[i - 1] + nums[i])
                if dec[i - 1] != -INF:
                    dec[i] = max(dec[i], dec[i - 1] + nums[i])
            if nums[i] > nums[i - 1]:
                if dec[i - 1] != -INF:
                    inc2[i] = max(inc2[i], dec[i - 1] + nums[i])

            if inc2[i] != -INF:
                best = max(best, inc2[i])

        return best if best != -INF else -1
