class Solution {
public:
    long long maxTrionicSubarraySum(std::vector<int>& nums) {
        int n = nums.size();
        if (n < 4) return -1;

        const long long INF = 1e16;
        std::vector<long long> inc1(n);
        std::vector<long long> peak(n, -INF);
        std::vector<long long> dec(n, -INF);
        std::vector<long long> inc2(n, -INF);

        for (int i = 0; i < n; ++i) inc1[i] = nums[i];

        long long best = -INF;
        for (int i = 1; i < n; ++i) {
            if (nums[i] > nums[i - 1]) {
                inc1[i] = std::max((long long)nums[i], inc1[i - 1] + nums[i]);
                peak[i] = inc1[i - 1] + nums[i];
                if (inc2[i - 1] != -INF) {
                    inc2[i] = std::max(inc2[i], inc2[i - 1] + nums[i]);
                }
                if (dec[i - 1] != -INF) {
                    inc2[i] = std::max(inc2[i], dec[i - 1] + nums[i]);
                }
            } else if (nums[i] < nums[i - 1]) {
                if (peak[i - 1] != -INF) {
                    dec[i] = std::max(dec[i], peak[i - 1] + nums[i]);
                }
                if (dec[i - 1] != -INF) {
                    dec[i] = std::max(dec[i], dec[i - 1] + nums[i]);
                }
            }
            if (inc2[i] != -INF) {
                best = std::max(best, inc2[i]);
            }
        }
        return best == -INF ? -1 : best;
    }
};

