var maxTrionicSubarraySum = function(nums) {
    const n = nums.length;
    if (n < 4) return -1;

    const INF = 1e16;
    const inc1 = new Float64Array(n);
    const peak = new Float64Array(n).fill(-INF);
    const dec = new Float64Array(n).fill(-INF);
    const inc2 = new Float64Array(n).fill(-INF);

    for (let i = 0; i < n; i++) inc1[i] = nums[i];

    let best = -INF;
    for (let i = 1; i < n; i++) {
        if (nums[i] > nums[i - 1]) {
            inc1[i] = Math.max(nums[i], inc1[i - 1] + nums[i]);
            peak[i] = inc1[i - 1] + nums[i];
            if (inc2[i - 1] !== -INF) {
                inc2[i] = Math.max(inc2[i], inc2[i - 1] + nums[i]);
            }
            if (dec[i - 1] !== -INF) {
                inc2[i] = Math.max(inc2[i], dec[i - 1] + nums[i]);
            }
        } else if (nums[i] < nums[i - 1]) {
            if (peak[i - 1] !== -INF) {
                dec[i] = Math.max(dec[i], peak[i - 1] + nums[i]);
            }
            if (dec[i - 1] !== -INF) {
                dec[i] = Math.max(dec[i], dec[i - 1] + nums[i]);
            }
        }
        if (inc2[i] !== -INF) {
            best = Math.max(best, inc2[i]);
        }
    }
    return best === -INF ? -1 : best;
};
